def polynomial (N : ℕ) (a : Arrays N) : Poly × Poly :=
  ∑ m : Fin N, ((∑ k, (a m).1 k • monomialAt (m.val + 1) k),
    ∑ k, (a m).2 k • monomialAt (m.val + 1) k)

